script:
var LIST=[{display:"He/Him",name:"hehim"},{display:"She/Her",name:"sheher"},{display:"They/Them",name:"theythem"}];
var USERS={mina:"sheher",rowan:"hehim",ode:"theythem"};
window.fetch=function(u){return new Promise(function(res,rej){
  var m=/users\/(\w+)$/.exec(u);
  if(/pronouns$/.test(u)) return res({ok:true,json:function(){return Promise.resolve(LIST)}});
  if(m) return res({ok:true,json:function(){return Promise.resolve(USERS[m[1]]?[{pronoun_id:USERS[m[1]]}]:[])}});
  rej(new Error("no avatar service in the picture"));
});};
function face(bg,skin){return "data:image/svg+xml;utf8,"+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><rect width="100" height="100" fill="'+bg+'"/><circle cx="50" cy="40" r="19" fill="'+skin+'"/><path d="M14 100 Q50 52 86 100Z" fill="'+skin+'"/></svg>')}
function smile(){return "data:image/svg+xml;utf8,"+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 40 40"><circle cx="20" cy="20" r="18" fill="#FFD36B"/><circle cx="14" cy="16" r="2.4" fill="#4a3320"/><circle cx="26" cy="16" r="2.4" fill="#4a3320"/><path d="M11 24 Q20 34 29 24" stroke="#4a3320" stroke-width="2.6" fill="none" stroke-linecap="round"/></svg>')}
var FACES={mina:face("#F6B6CF","#7A4B3A"),rowan:face("#A9D3F5","#E2B48F"),ode:face("#B8E3B0","#B6805C"),pip:face("#F5DFA1","#8A5A44")};
function say(nick,name,text,color,extra){var d={text:text,nick:nick,displayName:name,userId:"u-"+nick,msgId:"m-"+nick+Math.random(),badges:[],tags:{color:color},displayColor:color,emotes:[]};for(var k in (extra||{}))d[k]=extra[k];se("message",{data:d})}
say("mina","Mina","Good evening everyone, so happy to be here","#FF7BAC");
say("rowan","Rowan","That last bit was brilliant Kappa","#5BC0FF",{emotes:[{type:"twitch",name:"Kappa",id:"25",start:28,end:32,urls:{"2":"https://static-cdn.jtvnw.net/emoticons/v2/25/default/dark/2.0"}}],badges:[{type:"moderator",url:"https://static-cdn.jtvnw.net/badges/v1/3267646d-33f0-4b17-b3df-f923a41db1d0/1",description:"Moderator"}]});
say("ode","Ode","Sending you all a big hug today","#8FE388");
say("pip","Pip","waves at everyone","#FFD36B",{isAction:true});
setTimeout(function(){
  [].forEach.call(document.querySelectorAll(".cf-msg"),function(li){
    var n=li.getAttribute("data-id"), nick=["mina","rowan","ode","pip"][n]; var box=li.querySelector(".cf-avatar");
    if(box&&FACES[nick]){var img=document.createElement("img");img.src=FACES[nick];box.appendChild(img);}
    [].forEach.call(li.querySelectorAll(".cf-emote"),function(e){e.src=smile();});
    [].forEach.call(li.querySelectorAll(".cf-badges img"),function(b){b.src="data:image/svg+xml;utf8,"+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 18 18"><rect width="18" height="18" rx="3" fill="#00AD03"/><path d="M5 12 L9 5 L13 12Z" fill="#fff"/></svg>');});
  });
},1200);
